function validate([perm]) {
  if (!Array.isArray(perm)) return 'perm must be an array.';
  const n = perm.length;
  if (n < 1 || n > 100000) return 'perm needs 1 to 100000 values.';
  const seen = new Array(n + 1).fill(false);
  for (const v of perm) {
    if (!Number.isInteger(v) || v < 1 || v > n) return 'Every value must be between 1 and perm.length.';
    if (seen[v]) return 'perm must use each number from 1 to n exactly once.';
    seen[v] = true;
  }
  return null;
}

